import { Dropdown } from 'maeng-daisyui'
import { IonicGlobeOutline } from 'maeng-icons'
import { useRef } from 'react'
import { useTranslation } from 'react-i18next'

const TranslateButton = () => {
  const { i18n } = useTranslation()
  const currentLanguage = i18n.language
  const dropdownRef = useRef<HTMLDivElement>(null)

  const changeLanguage = (language: string) => {
    i18n.changeLanguage(language)

    if (dropdownRef.current) {
      const dropdown = dropdownRef.current.querySelector('details') as HTMLDetailsElement
      if (dropdown) {
        dropdown.open = false
      }
    }
  }

  return (
    <div ref={dropdownRef}>
      <Dropdown
        label={
          <div className="flex items-center gap-2">
            <IonicGlobeOutline /> Language
          </div>
        }
      >
        <ul
          tabIndex={0}
          className="dropdown-content menu bg-base-100 rounded-box z-1 w-[150px] p-2 shadow-sm gap-2"
        >
          <li>
            <button
              onClick={() => changeLanguage('ko')}
              className={currentLanguage === 'ko' ? 'active' : ''}
            >
              한국어
            </button>
          </li>
          <li>
            <button
              onClick={() => changeLanguage('en')}
              className={currentLanguage === 'en' ? 'active' : ''}
            >
              English
            </button>
          </li>
        </ul>
      </Dropdown>
    </div>
  )
}

export default TranslateButton
