import { IonicCloudDownloadOutline } from 'maeng-icons'
import { useTranslation } from 'maeng-utils/locale'

const DownloadButton = () => {
  const { i18n } = useTranslation()
  const currentLanguage = i18n.language
  const isKorean = currentLanguage === 'ko'
  return (
    <a className="btn m-[4px]" download href={isKorean ? '/portfolio_ko.pdf' : '/portfolio_en.pdf'}>
      <IonicCloudDownloadOutline className="w-6 h-6 mr-1" />
      Download
    </a>
  )
}

export default DownloadButton
